    advantage_gap = batch['advantage_gap']
    score = ops.mul(delta_log_prob, advantage_gap)
    neg_score = ops.relu(ops.neg(score))
    weight = batch.get('weight', None)
    if weight is not None:
        weighted_loss = ops.mul(neg_score, weight)
    else:
        weighted_loss = neg_score
    return weighted_loss.mean()

